bool CheckCookedSetValues(UScriptStruct* Tree,void* Memory){
 auto* Ints=CastField<FSetProperty>(FindDasStructField(Tree,TEXT("UniqueInts")));
 auto* Strings=CastField<FSetProperty>(FindDasStructField(Tree,TEXT("UniqueTexts")));
 auto* Empty=CastField<FSetProperty>(FindDasStructField(Tree,TEXT("EmptySet")));
 if(!Ints || !Strings || !Empty || !Ints->ElementProp->IsA<FIntProperty>() || !Strings->ElementProp->IsA<FStrProperty>())return false;
 FScriptSetHelper A(Ints,Ints->ContainerPtrToValuePtr<void>(Memory)),B(Strings,Strings->ContainerPtrToValuePtr<void>(Memory)),C(Empty,Empty->ContainerPtrToValuePtr<void>(Memory));
 bool Pass=A.Num()==2 && B.Num()==3 && C.Num()==0;
 for(int32 K:TArray<int32>{-3,7})Pass &= A.FindElementIndex(&K)!=INDEX_NONE;
 int32 Removed=42;Pass &= A.FindElementIndex(&Removed)==INDEX_NONE;
 for(const FString& K:TArray<FString>{TEXT(""),TEXT("Case"),TEXT("Ключ 世界")})Pass &= B.FindElementIndex(&K)!=INDEX_NONE;
 return Pass;
}
bool CheckCookedScalarMapValues(UScriptStruct* Tree,void* Memory){
 bool Pass=true;
 for(bool TextKey:{false,true}){
  const FString Prefix=TextKey?TEXT("Text"):TEXT("Int");
  for(const FString& Suffix:TArray<FString>{TEXT("Floats"),TEXT("Doubles"),TEXT("Bools"),TEXT("Names")}){
   auto* P=CastField<FMapProperty>(FindDasStructField(Tree,Prefix+Suffix));if(!P)return false;
   FScriptMapHelper Values(P,P->ContainerPtrToValuePtr<void>(Memory));Pass &= Values.Num()==2;
   for(int32 Ordinal=0;Ordinal<2;++Ordinal){
    int32 IntKey=Ordinal==0?-1:0;FString StringKey=Ordinal==0?TEXT("Ключ 世界"):TEXT("");
    const int32 I=TextKey?Values.FindMapIndexWithKey(&StringKey):Values.FindMapIndexWithKey(&IntKey);
    if(I==INDEX_NONE){Pass=false;continue;}const void* V=Values.GetValuePtr(I);
    if(Suffix==TEXT("Floats")){auto* T=CastField<FFloatProperty>(P->ValueProp);Pass &= T && T->GetPropertyValue(V)==(Ordinal==0?1.25f:-0.5f);}
    else if(Suffix==TEXT("Doubles")){auto* T=CastField<FDoubleProperty>(P->ValueProp);Pass &= T && T->GetPropertyValue(V)==(Ordinal==0?1.23456789012345:-9.87654321098765);}
    else if(Suffix==TEXT("Bools")){auto* T=CastField<FBoolProperty>(P->ValueProp);Pass &= T && T->GetPropertyValue(V)==(Ordinal==0);}
    else{auto* T=CastField<FNameProperty>(P->ValueProp);Pass &= T && T->GetPropertyValue(V)==(Ordinal==0?FName(TEXT("CaseKey_17")):NAME_None);}
   }
  }
 }
 return Pass;
}
